console.log(saudacao("Ana")); // funciona mesmo antes da definição, graças ao hoisting

function saudacao(nome) {
  return `Olá, ${nome}!`;
}

// a função tem nome próprio, útil em recursão e em stack traces
function fatorial(n) {
  if (n <= 1) return 1;
  return n * fatorial(n - 1);
}

console.log(fatorial(5)); // 120

const somar = function (a, b) {
  return a + b;
};

console.log(somar(2, 3)); // 5

// função nomeada dentro de uma expressão: o nome só existe dentro do próprio corpo
const fibonacci = function fib(n) {
  return n <= 1 ? n : fib(n - 1) + fib(n - 2);
};

console.log(fibonacci(10)); // 55
// console.log(fib(10)); // ReferenceError: fib is not defined

// parâmetro único: parênteses são opcionais
const dobro = x => x * 2;
const dobroExplicito = (x) => x * 2;

// zero ou vários parâmetros: parênteses obrigatórios
const saudar = () => "Olá!";
const somar = (a, b) => a + b;

// corpo de expressão: retorno implícito, sem chavetas
const quadrado = n => n ** 2;

// corpo de bloco: chavetas + return explícito
const calcularComImposto = valor => {
  const taxa = 0.23;
  return valor * (1 + taxa);
};

// devolver um objeto literal a partir de um corpo de expressão exige parênteses,
// para o motor não interpretar as chavetas como início de um bloco
const criarPonto = (x, y) => ({ x, y });

console.log(criarPonto(1, 2)); // { x: 1, y: 2 }

const contador = {
  valor: 0,
  metodoNormal() {
    // "this" aqui é o objeto contador, porque foi chamado como contador.metodoNormal()
    setTimeout(function () {
      // função normal: "this" aqui NÃO é o contador
      console.log(this?.valor); // undefined
    }, 0);
  },
  metodoComArrow() {
    setTimeout(() => {
      // arrow function: "this" é herdado do contexto onde foi definida, metodoComArrow
      console.log(this.valor); // 0
    }, 0);
  },
};

contador.metodoNormal();
contador.metodoComArrow();

function normal() {
  console.log(arguments.length);
}
normal(1, 2, 3); // 3

function Pessoa(nome) {
  this.nome = nome;
}
const p = new Pessoa("Rui"); // funciona: function declaration serve como construtor
console.log(p.nome); // Rui

const PessoaArrow = (nome) => {
  this.nome = nome;
};
// new PessoaArrow("Rui"); // TypeError: PessoaArrow is not a constructor

const usarMaiusculas = true;

// declaration: função utilitária de topo, disponível em qualquer ponto do ficheiro
function paraMaiusculas(texto) {
  return texto.toUpperCase();
}

// expression: atribuída condicionalmente, só existe a partir daqui
const formatar = usarMaiusculas
  ? function (texto) { return paraMaiusculas(texto); }
  : function (texto) { return texto; };

// arrow: callback conciso que preserva o "this" do método envolvente
const relatorio = {
  titulo: "Vendas",
  linhas: ["produto a", "produto b"],
  imprimir() {
    this.linhas.forEach(linha => console.log(`${this.titulo}: ${linha}`));
  },
};

relatorio.imprimir();
console.log(formatar("total mensal"));

exercises.statement:
Analisa o código abaixo e responde, por escrito, se cada chamada a seguir funciona ou lança erro, e explica porquê:

console.log(dobrar(4));
console.log(triplicar(4));

function dobrar(n) {
  return n * 2;
}

const triplicar = function (n) {
  return n * 3;
};

Depois, corrige o código (sem alterares o tipo de nenhuma das duas funções) para que ambas as chamadas funcionem.

exercises.solution_code:
// dobrar(4) funciona: function declaration é hoisted por completo (nome + corpo),
// por isso já está disponível antes da sua definição textual no código.
// triplicar(4) lança "ReferenceError: Cannot access 'triplicar' before initialization",
// porque o hoisting de "const triplicar" cria apenas o binding, deixando-o em
// temporal dead zone; a função só fica associada a esse nome quando a linha
// "const triplicar = ..." é efetivamente executada.

// Correção: garantir que as chamadas ocorrem depois de ambas as definições.

function dobrar(n) {
  return n * 2;
}

const triplicar = function (n) {
  return n * 3;
};

console.log(dobrar(4));    // 8
console.log(triplicar(4)); // 12

const operacoes = {
  somar: (a, b) => a + b,
  subtrair: (a, b) => a - b,
  multiplicar: (a, b) => {
    const produto = a * b;
    return produto;
  },
  criarResultado: (operacao, valor) => ({ operacao, valor }),
};

console.log(operacoes.criarResultado("soma", operacoes.somar(2, 3)));
// { operacao: 'soma', valor: 5 }

exercises.statement:
O objeto abaixo devia imprimir, com um segundo de intervalo entre cada linha, mensagens do tipo "Tarefa 1: comprar leite (pendente)", usando o prefixo guardado em this.prefixo. Ao correr o código atual, todas as mensagens aparecem com o prefixo undefined. Identifica a causa exata do problema e corrige o código, alterando apenas o tipo das funções necessárias (não alteres a lógica nem uses bind).

const gestor = {
  prefixo: "Tarefa",
  tarefas: ["comprar leite", "pagar renda", "estudar JS"],
  listar() {
    this.tarefas.forEach(function (tarefa, indice) {
      setTimeout(function () {
        console.log(`${this.prefixo} ${indice + 1}: ${tarefa} (pendente)`);
      }, (indice + 1) * 1000);
    });
  },
};

gestor.listar();

