const gestor = {
  prefixo: "Tarefa",
  tarefas: ["comprar leite", "pagar renda", "estudar JS"],
  listar() {
    this.tarefas.forEach((tarefa, indice) => {
      setTimeout(() => {
        console.log(`${this.prefixo} ${indice + 1}: ${tarefa} (pendente)`);
      }, (indice + 1) * 1000);
    });
  },
};

gestor.listar();
// Tarefa 1: comprar leite (pendente)
// Tarefa 2: pagar renda (pendente)
// Tarefa 3: estudar JS (pendente)

exercises.statement:
O código abaixo tenta criar objetos Produto, mas lança "TypeError: Produto is not a constructor" na linha do new. Explica exatamente por que razão uma arrow function não pode desempenhar este papel e reescreve Produto (mantendo os mesmos parâmetros e o mesmo corpo) como function declaration, de forma a que new Produto("Teclado", 45) funcione e devolva um objeto com as propriedades nome e preco.

const Produto = (nome, preco) => {
  this.nome = nome;
  this.preco = preco;
};

const item = new Produto("Teclado", 45);
console.log(item.nome, item.preco);

exercises.solution_code:
function Produto(nome, preco) {
  this.nome = nome;
  this.preco = preco;
}

const item = new Produto("Teclado", 45);
console.log(item.nome, item.preco); // Teclado 45
